namespace {

std::mutex gDetectedAppIdentityMutex;
std::string gDetectedAppDisplayName{"Target Game"};
std::string gDetectedAppVersionName;
long gDetectedAppVersionCode{0};
bool gDetectedAppIdentityReady{false};

std::string JniStringToUtf8(JNIEnv *env, jstring value) {
    if (env == nullptr || value == nullptr) {
        return {};
    }
    const char *chars = env->GetStringUTFChars(value, nullptr);
    if (chars == nullptr) {
        return {};
    }
    std::string result(chars);
    env->ReleaseStringUTFChars(value, chars);
    return result;
}

void ClearPendingJniException(JNIEnv *env) {
    if (env != nullptr && env->ExceptionCheck()) {
        env->ExceptionClear();
    }
}

std::string EscapeRichText(std::string value) {
    std::string escaped;
    escaped.reserve(value.size());
    for (char ch : value) {
        switch (ch) {
            case '&':
                escaped += "&amp;";
                break;
            case '<':
                escaped += "&lt;";
                break;
            case '>':
                escaped += "&gt;";
                break;
            case '\'':
                escaped += "&#39;";
                break;
            case '"':
                escaped += "&quot;";
                break;
            default:
                escaped += ch;
                break;
        }
    }
    return escaped;
}

std::string UpperAscii(std::string value) {
    std::transform(value.begin(), value.end(), value.begin(), [](unsigned char ch) {
        return static_cast<char>(std::toupper(ch));
    });
    return value;
}

void DetectAppIdentity(JNIEnv *env, jobject context) {
    if (env == nullptr || context == nullptr) {
        return;
    }

    std::string detectedName;
    std::string detectedVersion;
    long detectedVersionCode = 0;

    jclass contextClass = env->GetObjectClass(context);
    if (contextClass == nullptr) {
        ClearPendingJniException(env);
        return;
    }

    jmethodID getPackageManager = env->GetMethodID(
            contextClass, OBFUSCATE("getPackageManager"),
            OBFUSCATE("()Landroid/content/pm/PackageManager;"));
    jmethodID getPackageName = env->GetMethodID(
            contextClass, OBFUSCATE("getPackageName"), OBFUSCATE("()Ljava/lang/String;"));
    if (getPackageManager == nullptr || getPackageName == nullptr) {
        ClearPendingJniException(env);
        env->DeleteLocalRef(contextClass);
        return;
    }

    jobject packageManager = env->CallObjectMethod(context, getPackageManager);
    jstring packageName = static_cast<jstring>(env->CallObjectMethod(context, getPackageName));
    if (env->ExceptionCheck() || packageManager == nullptr || packageName == nullptr) {
        ClearPendingJniException(env);
        if (packageManager != nullptr) env->DeleteLocalRef(packageManager);
        if (packageName != nullptr) env->DeleteLocalRef(packageName);
        env->DeleteLocalRef(contextClass);
        return;
    }

    jclass packageManagerClass = env->GetObjectClass(packageManager);
    if (packageManagerClass != nullptr) {
        jmethodID getPackageInfo = env->GetMethodID(
                packageManagerClass, OBFUSCATE("getPackageInfo"),
                OBFUSCATE("(Ljava/lang/String;I)Landroid/content/pm/PackageInfo;"));
        jmethodID getApplicationLabel = env->GetMethodID(
                packageManagerClass, OBFUSCATE("getApplicationLabel"),
                OBFUSCATE("(Landroid/content/pm/ApplicationInfo;)Ljava/lang/CharSequence;"));

        jobject packageInfo = nullptr;
        if (getPackageInfo != nullptr) {
            packageInfo = env->CallObjectMethod(packageManager, getPackageInfo, packageName, 0);
            if (env->ExceptionCheck()) {
                ClearPendingJniException(env);
                packageInfo = nullptr;
            }
        }

        if (packageInfo != nullptr) {
            jclass packageInfoClass = env->GetObjectClass(packageInfo);
            if (packageInfoClass != nullptr) {
                jfieldID versionNameField = env->GetFieldID(
                        packageInfoClass, OBFUSCATE("versionName"),
                        OBFUSCATE("Ljava/lang/String;"));
                if (versionNameField != nullptr) {
                    auto versionName = static_cast<jstring>(
                            env->GetObjectField(packageInfo, versionNameField));
                    detectedVersion = JniStringToUtf8(env, versionName);
                    if (versionName != nullptr) env->DeleteLocalRef(versionName);
                } else {
                    ClearPendingJniException(env);
                }

                jfieldID versionCodeField = env->GetFieldID(
                        packageInfoClass, OBFUSCATE("versionCode"), OBFUSCATE("I"));
                if (versionCodeField != nullptr) {
                    detectedVersionCode = static_cast<long>(
                            env->GetIntField(packageInfo, versionCodeField));
                } else {
                    ClearPendingJniException(env);
                }

                jfieldID appInfoField = env->GetFieldID(
                        packageInfoClass, OBFUSCATE("applicationInfo"),
                        OBFUSCATE("Landroid/content/pm/ApplicationInfo;"));
                jobject applicationInfo = nullptr;
                if (appInfoField != nullptr) {
                    applicationInfo = env->GetObjectField(packageInfo, appInfoField);
                } else {
                    ClearPendingJniException(env);
                }

                if (applicationInfo != nullptr && getApplicationLabel != nullptr) {
                    jobject label = env->CallObjectMethod(
                            packageManager, getApplicationLabel, applicationInfo);
                    if (!env->ExceptionCheck() && label != nullptr) {
                        jclass labelClass = env->GetObjectClass(label);
                        if (labelClass != nullptr) {
                            jmethodID toString = env->GetMethodID(
                                    labelClass, OBFUSCATE("toString"),
                                    OBFUSCATE("()Ljava/lang/String;"));
                            if (toString != nullptr) {
                                auto labelText = static_cast<jstring>(
                                        env->CallObjectMethod(label, toString));
                                detectedName = JniStringToUtf8(env, labelText);
                                if (labelText != nullptr) env->DeleteLocalRef(labelText);
                            } else {
                                ClearPendingJniException(env);
                            }
                            env->DeleteLocalRef(labelClass);
                        }
                        env->DeleteLocalRef(label);
                    } else {
                        ClearPendingJniException(env);
                    }
                    env->DeleteLocalRef(applicationInfo);
                }

                env->DeleteLocalRef(packageInfoClass);
            }
            env->DeleteLocalRef(packageInfo);
        }

        env->DeleteLocalRef(packageManagerClass);
    } else {
        ClearPendingJniException(env);
    }

    env->DeleteLocalRef(packageName);
    env->DeleteLocalRef(packageManager);
    env->DeleteLocalRef(contextClass);

    std::lock_guard<std::mutex> lock(gDetectedAppIdentityMutex);
    if (!detectedName.empty()) {
        gDetectedAppDisplayName = detectedName;
        gDetectedAppIdentityReady = true;
    }
    gDetectedAppVersionName = detectedVersion;
    if (detectedVersionCode > 0) {
        gDetectedAppVersionCode = detectedVersionCode;
    }
}

} // namespace

std::string DetectedAppDisplayName() {
    std::lock_guard<std::mutex> lock(gDetectedAppIdentityMutex);
    return gDetectedAppDisplayName;
}

std::string DetectedAppVersionName() {
    std::lock_guard<std::mutex> lock(gDetectedAppIdentityMutex);
    return gDetectedAppVersionName;
}

long DetectedAppVersionCode() {
    std::lock_guard<std::mutex> lock(gDetectedAppIdentityMutex);
    return gDetectedAppVersionCode;
}

std::string DetectedAppIdentityLabel() {
    std::lock_guard<std::mutex> lock(gDetectedAppIdentityMutex);
    if (!gDetectedAppIdentityReady) {
        return {};
    }
    std::string label = EscapeRichText(gDetectedAppDisplayName);
    if (!gDetectedAppVersionName.empty()) {
        label += " ";
        label += EscapeRichText(gDetectedAppVersionName);
    }
    return label;
}

void Init(JNIEnv *env, jobject thiz, jobject ctx, jobject title, jobject subtitle) {
    DetectAppIdentity(env, ctx);

    const std::string displayName = EscapeRichText(UpperAscii(DetectedAppDisplayName()));
    const std::string versionName = EscapeRichText(DetectedAppVersionName());
    std::string titleText = "<b><font color='#F4F7FA'>";
    titleText += displayName;
    titleText += "</font>";
    if (!versionName.empty()) {
        titleText += " <font color='#E8B86A'>";
        titleText += versionName;
        titleText += "</font>";
    }
    titleText += "</b>";
    setText(env, title, titleText.c_str());

    setText(env, subtitle, OBFUSCATE("<b><marquee>"
                                     "<font color='#8E9AA3'>Jester control panel</font>"
                                     "</marquee></b>"));

    if (!brandingToastShown.test_and_set()) {
        Toast(env, ctx, OBFUSCATE("Menu by VOIDMOD1"), ToastLength::LENGTH_LONG);
    }
}

